-- ===========================================================================
-- MODELOS DE GENERADOR Y KITS DE MANTENIMIENTO
--
-- Generado una vez desde REFACCIONAMIENTO GENERAC.xlsx (hojas Air Cooled y Liquid Cooled).
-- Sus kits ya no valen: la 95 los rehízo sin bujías. Si se repite este script, correr la 95 después.
--
-- `modelos_generador` es el catálogo de referencia: modelo, capacidad, enfriamiento y los
-- códigos del Excel, TODOS, aunque la pieza todavía no esté en `productos`.
--
-- Un kit es una fila de `paquetes_mantenimiento` con `kit = true`: filtro de aceite, filtro de
-- aire y bujía de los modelos que comparten esas piezas. Solo lleva lo que ya está en el
-- catálogo; lo que falta queda escrito en `notas` para agregarlo desde Precios. Sirve igual para
-- preventivo menor y mayor, y se aplica por el modelo del equipo, nunca por clase: por eso los
-- kits se excluyen de la búsqueda general (no tienen marca, modelo ni clase, y sin ese filtro
-- le tocarían a cualquier equipo).
--
-- Se puede repetir: no pisa las piezas que el admin les agregue a los kits.
-- Prueba: 94_prueba_modelos_generador.sql.
-- ===========================================================================

alter table paquetes_mantenimiento add column if not exists kit boolean not null default false;

-- La misma clave para el Excel y para lo que se escriba en un equipo: "g00703-11" = G0070311.
create or replace function _clave_modelo(p text) returns text
language sql immutable set search_path = public as $$
  select nullif(upper(regexp_replace(coalesce(p, ''), '[^a-zA-Z0-9]', '', 'g')), '')
$$;

create table if not exists modelos_generador (
  modelo text primary key,             -- ya normalizado con _clave_modelo
  marca text not null default 'Generac',
  capacidad_kw numeric not null,
  enfriamiento text not null check (enfriamiento in ('air_cooled', 'liquid_cooled')),
  descripcion text,
  filtro_aceite text,
  filtro_aire text,
  bujia text,
  paquete_id uuid references paquetes_mantenimiento(id) on delete set null,
  created_at timestamptz not null default now()
);
create index if not exists idx_modelos_generador_paquete on modelos_generador(paquete_id);

-- Sin precios: lo leen también el técnico y el almacén. Solo el admin lo cambia.
alter table modelos_generador enable row level security;
revoke all on modelos_generador from anon;
drop policy if exists "leen_modelos_generador" on modelos_generador;
create policy "leen_modelos_generador" on modelos_generador for select to authenticated
  using (mi_rol() in ('admin', 'tecnico', 'almacenista'));
drop policy if exists "admin_modelos_generador" on modelos_generador;
create policy "admin_modelos_generador" on modelos_generador for all to authenticated
  using (es_admin()) with check (es_admin());

-- ---------------------------------------------------------------------------
-- Las piezas que ya están en el catálogo y son la misma: el original y su genérico.
-- ---------------------------------------------------------------------------
update productos set grupo_equivalente = 'FILTRO-ACEITE-070185'
 where sku in ('070185ES', '070185ES-G') and grupo_equivalente is null;

-- ---------------------------------------------------------------------------
-- Kits y modelos.
-- ---------------------------------------------------------------------------

on conflict (modelo) do nothing;

-- ---------------------------------------------------------------------------
-- El equipo aprende de su modelo.
--
-- Un trigger y no la pantalla: el equipo también nace desde la orden del técnico y desde la
-- oficina. Solo llena huecos: lo capturado a mano no se pisa.
-- ---------------------------------------------------------------------------
create or replace function _equipo_desde_modelo() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  m modelos_generador%rowtype;
begin
  if new.tipo = 'generador' then
    select * into m from modelos_generador where modelo = _clave_modelo(new.modelo);
    if found then
      new.marca := coalesce(nullif(trim(new.marca), ''), m.marca);
      new.capacidad_kw := coalesce(nullif(new.capacidad_kw, 0), m.capacidad_kw);
      if coalesce(new.atributos ->> 'enfriamiento', '') = '' then
        new.atributos := coalesce(new.atributos, '{}'::jsonb)
                         || jsonb_build_object('enfriamiento', m.enfriamiento);
      end if;
    end if;
  end if;
  return new;
end $$;
revoke all on function _equipo_desde_modelo() from public, anon, authenticated;

drop trigger if exists equipo_desde_modelo on equipos;
create trigger equipo_desde_modelo before insert or update on equipos
  for each row execute function _equipo_desde_modelo();

-- ---------------------------------------------------------------------------
-- Qué paquete le toca a un equipo (de la 29). Orden: el capturado para ese modelo exacto, el
-- kit de su modelo y luego lo general. El kit no mira `tipo`: sirve para menor y mayor.
-- ---------------------------------------------------------------------------
create or replace function _paquete_de_equipo(p_equipo uuid, p_tipo text) returns uuid
language sql stable security definer set search_path = public as $$
  select p.id
    from equipos e
    left join modelos_generador m on e.tipo = 'generador' and m.modelo = _clave_modelo(e.modelo)
    join paquetes_mantenimiento p on p.activo and (
      (p.kit and p.id = m.paquete_id)
      or (not p.kit and p.tipo = p_tipo
          and (p.marca is null or lower(p.marca) = lower(coalesce(e.marca, '')))
          and (p.modelo is null or lower(p.modelo) = lower(coalesce(e.modelo, '')))
          and (p.clase is null or p.clase = _clase_de_equipo(e))
          and (p.kw_desde is null or _capacidad_de_equipo(e) >= p.kw_desde)
          and (p.kw_hasta is null or _capacidad_de_equipo(e) <= p.kw_hasta)))
   where e.id = p_equipo
   order by (p.modelo is not null) desc, p.kit desc, (p.marca is not null) desc,
            (p.clase is not null) desc, p.kw_desde desc nulls last
   limit 1
$$;
revoke all on function _paquete_de_equipo(uuid, text) from public, anon, authenticated;

  on conflict (archivo) do nothing;

notify pgrst, 'reload schema';
